    int numRows = grid.length;
    int numCols = grid[0].length;
    boolean[][] visited = new boolean[numRows][numCols];
    int depositCount = 0;

    for (int i = 0; i < numRows; i++) {
        for (int j = 0; j < numCols; j++) {
            if (grid[i][j] == '@' && !visited[i][j]) {
                depositCount++;
                dfs(grid, visited, i, j);
            }
        }
    }

    return depositCount;
}

private static void dfs(char[][] grid, boolean[][] visited, int row, int col) {
    int[] rowDirections = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] colDirections = {-1, 0, 1, -1, 1, -1, 0, 1};

    visited[row][col] = true;

    for (int d = 0; d < 8; d++) {
        int newRow = row + rowDirections[d];
        int newCol = col + colDirections[d];

        if (newRow >= 0 && newRow < grid.length && newCol >= 0 && newCol < grid[0].length &&
            grid[newRow][newCol] == '@' && !visited[newRow][newCol]) {
            dfs(grid, visited, newRow, newCol);
        }
    }
}

public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("Number of triangles N must be non-negative.");
    }
    // The formula to calculate the maximum number of regions
    // formed by N triangles is given by:
    // R(N) = 2 + 3 * N + N * (N - 1) / 2
    // This formula is derived from the fact that each new triangle
    // can intersect with all previous triangles in 3 new edges,
    // adding 3 * N new regions, plus the regions formed by the
    // intersections of the new triangle with the previous ones.
    return 2 + 3 * N + N * (N - 1) / 2;
}

