    word1 = word1.toUpperCase();
    word2 = word2.toUpperCase();

    int commonCount = 0;
    boolean[] usedInWord2 = new boolean[word2.length()];

    for (int i = 0; i < word1.length(); i++) {
        char c = word1.charAt(i);
        for (int j = 0; j < word2.length(); j++) {
            if (c == word2.charAt(j) && !usedInWord2[j]) {
                commonCount++;
                usedInWord2[j] = true;
                break;
            }
        }
    }

    int totalLength = word1.length() + word2.length();
    int gcd = gcd(commonCount, totalLength);

    String result = "appx(" + word1 + ", " + word2 + ") = " + (commonCount / gcd) + "/" + (totalLength / gcd);
    return result;
}

private static int gcd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

public static String convertDatesToWeekdays(String date) {
    try {
        String[] parts = date.split(" ");
        if (parts.length != 3) {
            return "Invalid date format";
        }

        int month = Integer.parseInt(parts[0]);
        int day = Integer.parseInt(parts[1]);
        int year = Integer.parseInt(parts[2]);

        String[] months = {"January", "February", "March", "April", "May", "June",
                            "July", "August", "September", "October", "November", "December"};
        String[] weekdays = {"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"};

        if (month < 1 || month > 12 || day < 1 || day > 31) {
            return "Invalid date";
        }

        java.util.Calendar cal = java.util.Calendar.getInstance();
        cal.set(year, month - 1, day);
        int dayOfWeek = cal.get(java.util.Calendar.DAY_OF_WEEK);

        return months[month - 1] + " " + day + ", " + year + " is a " + weekdays[dayOfWeek - 1];
    } catch (NumberFormatException e) {
        return "Invalid date format";
    }
}

