public int search(int[] nums, int target) {
    if (nums == null || nums.length == 0) {
        return -1;
    }

    int left = 0;
    int right = nums.length - 1;

    while (left <= right) {
        int mid = left + (right - left) / 2;

        if (nums[mid] == target) {
            return mid;
        }

        if (nums[left] <= nums[mid]) {
            if (nums[left] <= target && target < nums[mid]) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        } else {
            if (nums[mid] < target && target <= nums[right]) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
    }

    return -1;
}

public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        throw new IllegalArgumentException("Array must not be null or empty");
    }

    int n = arr.length;
    int trimSize = (int) (n * 0.05);

    if (trimSize * 2 >= n) {
        throw new IllegalArgumentException("Array size is too small to trim 5% from both ends");
    }

    Arrays.sort(arr);

    double sum = 0;
    for (int i = trimSize; i < n - trimSize; i++) {
        sum += arr[i];
    }

    return sum / (n - 2 * trimSize);
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0) {
        return false;
    }

    int[] remainderCount = new int[k];

    for (int num : arr) {
        int remainder = (num % k + k) % k; // Handle negative numbers
        remainderCount[remainder]++;
    }

    if (remainderCount[0] % 2 != 0) {
        return false;
    }

    for (int i = 1; i <= k / 2; i++) {
        if (remainderCount[i] != remainderCount[k - i]) {
            return false;
        }
    }

    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    List<List<Integer>> tree = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        tree.add(new ArrayList<>());
    }
    for (int[] edge : edges) {
        tree.get(edge[0]).add(edge[1]);
        tree.get(edge[1]).add(edge[0]);
    }
    return dfs(0, -1, tree, hasApple);
}

private int dfs(int node, int parent, List<List<Integer>> tree, boolean[] hasApple) {
    int totalTime = 0;
    for (int child : tree.get(node)) {
        if (child == parent) continue; // Skip the parent node to avoid cycles
        int childTime = dfs(child, node, tree, hasApple);
        if (childTime > 0 || hasApple[child]) {
            totalTime += childTime + 2; // Add 2 for the round trip to the child
        }
    }
    return totalTime;
}

public String sortString(String s) {
    if (s == null || s.length() == 0) {
        return s;
    }

    int[] charCount = new int[26];
    for (char c : s.toCharArray()) {
        charCount[c - 'a']++;
    }

    StringBuilder result = new StringBuilder();
    int length = s.length();

    while (result.length() < length) {
        // Step 1 to 3: Pick smallest characters in ascending order
        for (int i = 0; i < 26; i++) {
            if (charCount[i] > 0) {
                result.append((char) (i + 'a'));
                charCount[i]--;
            }
        }

        // Step 4 to 6: Pick largest characters in descending order
        for (int i = 25; i >= 0; i--) {
            if (charCount[i] > 0) {
                result.append((char) (i + 'a'));
                charCount[i]--;
            }
        }
    }

    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int totalSum = 0;
    int n = nums.length;
    for (int num : nums) {
        totalSum += num;
    }

    // Try to find a subset of size s (1 <= s <= n/2) with sum = totalSum * s / n
    boolean[][] isPossible = new boolean[n / 2 + 1][totalSum + 1];
    int[][] count = new int[n / 2 + 1][totalSum + 1];
    isPossible[0][0] = true;
    count[0][0] = 1;

    for (int num : nums) {
        for (int s = n / 2; s >= 1; s--) {
            for (int sum = 0; sum <= totalSum - num; sum++) {
                if (isPossible[s - 1][sum]) {
                    isPossible[s][sum + num] = true;
                    count[s][sum + num] += count[s - 1][sum];
                }
            }
        }
    }

    for (int s = 1; s <= n / 2; s++) {
        if (totalSum * s % n == 0 && isPossible[s][totalSum * s / n]) {
            // We found a subset with the required sum
            int subsetSum = totalSum * s / n;
            if (count[s][subsetSum] < (1 << s)) {
                return true;
            }
        }
    }

    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    if (cost.length == 1) {
        return cost[0];
    }

    int[] dp = new int[cost.length + 1];
    dp[0] = 0;
    dp[1] = 0;

    for (int i = 2; i <= cost.length; i++) {
        dp[i] = Math.min(dp[i - 1] + cost[i - 1], dp[i - 2] + cost[i - 2]);
    }

    return dp[cost.length];
}

