public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) {
        return result;
    }

    for (int i = 0; i <= 9; i++) {
        if (i >= low && i <= high) {
            result.add(i);
        }
        findSteppingNumbersHelper(i, low, high, result);
    }

    Collections.sort(result);
    return result;
}

private static void findSteppingNumbersHelper(int num, int low, int high, List<Integer> result) {
    if (num > high) {
        return;
    }
    if (num >= low) {
        result.add(num);
    }

    int lastDigit = num % 10;

    if (lastDigit > 0) {
        int nextNum = num * 10 + (lastDigit - 1);
        findSteppingNumbersHelper(nextNum, low, high, result);
    }
    if (lastDigit < 9) {
        int nextNum = num * 10 + (lastDigit + 1);
        findSteppingNumbersHelper(nextNum, low, high, result);
    }
}

public static int countDigitOne(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("The input must be a non-negative integer.");
    }

    int count = 0;
    for (long i = 1; i <= n; i *= 10) {
        long divider = i * 10;
        count += (n / divider) * i + Math.min(Math.max(n % divider - i + 1, 0), i);
    }
    return count;
}

