        int digit = n % 10;
        result.append(digit);
        count++;
        n /= 10;

        if (count == 3 && n > 0) {
            result.append('.');
            count = 0;
        }
    }

    return result.reverse().toString();
}

public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) return 0;
    boolean[] used = new boolean[A.length];
    int[] count = new int[1];
    backtrack(A, used, new ArrayList<>(), count);
    return count[0];
}

private static void backtrack(int[] A, boolean[] used, List<Integer> current, int[] count) {
    if (current.size() == A.length) {
        count[0]++;
        return;
    }
    Set<Integer> set = new HashSet<>(); // To avoid duplicate permutations
    for (int i = 0; i < A.length; i++) {
        if (used[i] || (i > 0 && A[i] == A[i - 1] && !used[i - 1]) || (current.size() > 0 && !isPerfectSquare(current.get(current.size() - 1), A[i]))) {
            continue;
        }
        used[i] = true;
        current.add(A[i]);
        backtrack(A, used, current, count);
        current.remove(current.size() - 1);
        used[i] = false;
    }
}

private static boolean isPerfectSquare(int a, int b) {
    int sum = a + b;
    int sqrt = (int) Math.sqrt(sum);
    return sqrt * sqrt == sum;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }

    int maxArea = 0;
    int[] stack = new int[heights.length];
    int top = -1;

    for (int i = 0; i < heights.length; i++) {
        while (top != -1 && heights[i] <= heights[stack[top]]) {
            int h = heights[stack[top--]];
            int left = top == -1 ? -1 : stack[top];
            maxArea = Math.max(maxArea, (i - left - 1) * h);
        }
        stack[++top] = i;
    }

    while (top != -1) {
        int h = heights[stack[top--]];
        int left = top == -1 ? -1 : stack[top];
        maxArea = Math.max(maxArea, (heights.length - left - 1) * h);
    }

    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }

    int n = mat.length;
    int m = mat[0].length;
    int[] result = new int[n * m];
    int row = 0, col = 0;

    for (int i = 0; i < result.length; i++) {
        result[i] = mat[row][col];
        if ((row + col) % 2 == 0) { // Move Up
            if (col == m - 1) {
                row++;
            } else if (row == 0) {
                col++;
            } else {
                row--;
                col++;
            }
        } else { // Move Down
            if (row == n - 1) {
                col++;
            } else if (col == 0) {
                row++;
            } else {
                row++;
                col--;
            }
        }
    }

    return result;
}

public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    int len = digits.length;

    // Step 1: Find the rightmost digit that is smaller than the digit next to it
    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }

    // If no such digit is found, return -1
    if (i == -1) {
        return -1;
    }

    // Step 2: Find the smallest digit on the right side of the found digit that is larger than it
    int j = len - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }

    // Step 3: Swap the found digits
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Step 4: Sort the digits on the right side of the original position of the first found digit
    Arrays.sort(digits, i + 1, len);

    // Convert the array of characters back to an integer
    try {
        return Integer.parseInt(new String(digits));
    } catch (NumberFormatException e) {
        return -1; // In case the resulting number is out of the integer range
    }
}

public static List<String> centerSymmetricNumbers(int n) {
    if (n <= 0) {
        return Collections.emptyList();
    }
    return helper(n, n);
}

private static List<String> helper(int currentLength, int targetLength) {
    if (currentLength == 0) {
        return Collections.singletonList("");
    }
    if (currentLength == 1) {
        return Arrays.asList("0", "1", "8");
    }

    List<String> subResult = helper(currentLength - 2, targetLength);
    List<String> result = new ArrayList<>();

    for (String s : subResult) {
        if (currentLength != targetLength) {
            result.add("0" + s + "0");
        }
        result.add("1" + s + "1");
        result.add("6" + s + "9");
        result.add("8" + s + "8");
        result.add("9" + s + "6");
    }

    return result;
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3 || points[0].length != 2 || points[1].length != 2 || points[2].length != 2) {
        throw new IllegalArgumentException("Input must be a 2D array of exactly three points, each with two coordinates.");
    }

    int dx1 = points[1][0] - points[0][0];
    int dy1 = points[1][1] - points[0][1];
    int dx2 = points[2][0] - points[0][0];
    int dy2 = points[2][1] - points[0][1];

    // The points form a boomerang if the vectors (dx1, dy1) and (dx2, dy2) are not collinear
    // This is true if the cross product of the vectors is not zero
    // dx1 * dy2 != dx2 * dy1
    return dx1 * dy2 != dx2 * dy1;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("The index must be a positive integer.");
    }

    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;

    int index2 = 0, index3 = 0, index5 = 0;
    int nextMultipleOf2 = 2;
    int nextMultipleOf3 = 3;
    int nextMultipleOf5 = 5;

    for (int i = 1; i < n; i++) {
        int nextUglyNumber = Math.min(nextMultipleOf2, Math.min(nextMultipleOf3, nextMultipleOf5));
        uglyNumbers[i] = nextUglyNumber;

        if (nextUglyNumber == nextMultipleOf2) {
            index2++;
            nextMultipleOf2 = uglyNumbers[index2] * 2;
        }
        if (nextUglyNumber == nextMultipleOf3) {
            index3++;
            nextMultipleOf3 = uglyNumbers[index3] * 3;
        }
        if (nextUglyNumber == nextMultipleOf5) {
            index5++;
            nextMultipleOf5 = uglyNumbers[index5] * 5;
        }
    }

    return uglyNumbers[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.length() == 0) {
        return 0;
    }

    int maxLength = 1;
    int currentLength = 1;

    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentLength++;
        } else {
            maxLength = Math.max(maxLength, currentLength);
            currentLength = 1;
        }
    }

    // Check the last sequence
    maxLength = Math.max(maxLength, currentLength);

    return maxLength;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n < 1) {
        return result;
    }

    for (int i = 1; i <= 9; i++) {
        dfs(result, i, n);
    }
    return result;
}

private static void dfs(List<Integer> result, int current, int n) {
    if (current > n) {
        return;
    }
    result.add(current);
    for (int i = 0; i <= 9; i++) {
        dfs(result, current * 10 + i, n);
    }
}

public static int calculateUniqueSum(int[] nums) {
    Map<Integer, Integer> counts = new HashMap<>();
    for (int num : nums) {
        counts.put(num, counts.getOrDefault(num, 0) + 1);
    }
    int sum = 0;
    for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer.");
    }

    int[] dp = new int[n + 1];
    for (int i = 1; i <= n; i++) {
        dp[i] = i; // Initialize with the worst case, i.e., 1+1+...+1 (i times)
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    String[] words = s.split(" ");
    StringBuilder reversedSentence = new StringBuilder();

    for (String word : words) {
        StringBuilder reversedWord = new StringBuilder(word).reverse();
        reversedSentence.append(reversedWord.toString()).append(" ");
    }

    // Trim the last space and return the result
    return reversedSentence.toString().trim();
}
